export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const parsed = parseQuery(searchParams, productSearchQuerySchema);
    if (!parsed.success) return parsed.response;
    const query = parsed.data.q ?? "";

    if (!query.trim()) {
      return NextResponse.json({ products: [] });
    }

    if (isAccessingProtectedTable(query)) {
      return NextResponse.json(
        {
          error:
            "Access to the flags and hints tables is not allowed... Well, that's a shame... You'll have to find another way to get them all...",
          products: [],
        },
        { status: 403 }
      );
    }

    const sqlQuery = `
      SELECT
        id,
        name,
        description,
        price,
        "imageUrl"
      FROM products
      WHERE name LIKE '%${query}%' OR description LIKE '%${query}%'
      ORDER BY name ASC
      LIMIT 50
    `;

    let results: Record<string, unknown>[] = [];
    try {
      const queryResults = (await prisma.$queryRawUnsafe(sqlQuery)) as Record<
        string,
        unknown
      >[];

      results = stripFlagValues(queryResults);
    } catch (error) {
      logger.error(
        { err: error, route: "/api/products/search" },
        "Query error"
      );
      return NextResponse.json(
        {
          error: error instanceof Error ? error.message : "Search failed",
          products: [],
        },
        { status: 500 }
      );
    }

    const canary = await prisma.internalSecret.findUnique({
      where: { slug: CANARY_SLUG },
    });

    const response: {
      products: Record<string, unknown>[];
      flag?: string;
      message?: string;
