export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const parsed = parseQuery(searchParams, filesQuerySchema);
    if (!parsed.success) return parsed.response;
    const file = parsed.data.file ?? null;
    const listDir = parsed.data.list ?? null;
    const dirPath = parsed.data.path ?? "";

    const baseDir = join(process.cwd(), "documents");

    if (listDir === "true") {
      const targetDir = join(baseDir, dirPath);
      const entries = await readdir(targetDir, { withFileTypes: true });

      const items = await Promise.all(
        entries.map(async (entry) => {
          const fullPath = join(targetDir, entry.name);
          const stats = await stat(fullPath);
          return {
            name: entry.name,
            type: entry.isDirectory() ? "directory" : "file",
            size: stats.size,
            modified: stats.mtime.toISOString(),
          };
        })
      );

      return NextResponse.json({
        path: dirPath,
        items,
      });
    }

    if (!file) {
      return NextResponse.json(
        { error: "File parameter is required" },
        { status: 400 }
      );
    }

    const filePath = join(baseDir, file);
    const extension = extname(file).toLowerCase();

    if (extension === ".pdf") {
      const content = await readFile(filePath);
      return new NextResponse(content, {
        headers: {
          "Content-Type": "application/pdf",
          "Content-Disposition": `inline; filename="${file.split("/").pop()}"`,
        },
      });
    }

    const content = await readFile(filePath, "utf-8");

    return NextResponse.json({
      filename: file,
      content,
    });
  } catch (error) {
    logger.error({ err: error, route: "/api/files" }, "Error reading file");
    return NextResponse.json({ error: "Failed to read file" }, { status: 500 });
  }
}

export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, orderSearchBodySchema);
    if (!parsed.success) return parsed.response;
    const { status } = parsed.data;

    if (status && isAccessingProtectedTable(status)) {
      return NextResponse.json(
        {
          error:
            "Access to the flags and hints tables is not allowed... Well, that's a shame... You'll have to find another way to get them all...",
          orders: [],
        },
        { status: 403 }
      );
    }

    const statusFilter = status ? `AND o.status = '${status}'` : "";

    const query = `
      SELECT
        o.id,
        o.total,
        o.status,
        o."userId",
        a.street,
        a.city,
        a.state,
        a."zipCode",
        a.country
      FROM orders o
      INNER JOIN addresses a ON o."addressId" = a.id
      WHERE o."userId" = '${user.id}' ${statusFilter}
      ORDER BY o.id DESC
    `;

    let results: Record<string, unknown>[] = [];
    try {
      results = stripFlagValues(
        (await prisma.$queryRawUnsafe(query)) as Record<string, unknown>[]
      );
    } catch (error) {
      logger.error({ err: error, route: "/api/orders/search" }, "Query error");
      return NextResponse.json(
        {
          error: error instanceof Error ? error.message : "Search failed",
          orders: [],
        },
        { status: 500 }
      );
    }

    const canary = await prisma.internalSecret.findUnique({
      where: { slug: CANARY_SLUG },
    });

    const response: {
      orders: Record<string, unknown>[];
      flag?: string;
      message?: string;
    } = {
      orders: results,
    };

    if (hasExfiltratedCanary(results, canary, [status ?? ""])) {
      const flag = await prisma.flag.findUnique({
        where: { slug: CANARY_SLUG },
      });
      if (flag) {
        response.flag = flag.flag;
        response.message =
          "Internal secret exfiltrated through the order search! Well done!";
      }
    } else if (status && isSQLInjectionAttempt(status)) {
      response.message =
        "SQL syntax detected in the status filter." +
        " The flag tracks one specific internal secret, and it is not in these rows.";
    }

    return NextResponse.json(response);
  } catch (error) {
    logger.error(
      { err: error, route: "/api/orders/search" },
      "Error searching orders"
    );
    return NextResponse.json(
      { error: "Failed to search orders" },
      { status: 500 }
    );
  }
});

