{
  const { path = [] } = await params;
  const relative = path.join("/");

  const flag = await prisma.flag.findUnique({
    where: { slug: "exposed-git-repository" },
  });
  if (!flag) {
    throw new Error(
      "Flag exposed-git-repository is missing: seed the database"
    );
  }

  const repository = buildExposedRepository(flag.flag);

  const file = repository.get(relative);
  if (file) {
    return new NextResponse(new Uint8Array(file), {
      headers: { "Content-Type": "application/octet-stream" },
    });
  }

  const directory = relative === "" ? "" : `${relative}/`;
  const children = listChildren(repository, directory);
  if (children.size === 0) {
    return new NextResponse(NOT_FOUND, {
      status: 404,
      headers: { "Content-Type": "text/html" },
    });
  }

  // The rewrite keeps the requested pathname, trailing slash included.
  if (!request.nextUrl.pathname.endsWith("/")) {
    return NextResponse.redirect(
      new URL(`${PUBLIC_ROOT}${directory}`, request.url),
      301
    );
  }

  return new NextResponse(renderListing(directory, children), {
    headers: { "Content-Type": "text/html" },
  });
}

{
  try {
    const parsed = await parseBody(request, redeemGiftCardBodySchema);
    if (!parsed.success) return parsed.response;
    const { code: rawCode } = parsed.data;

    const normalized = rawCode.trim().toUpperCase();

    const candidates = await prisma.giftCard.findMany({
      where: { status: "PENDING" },
      select: { id: true, code: true, amount: true, buyerId: true },
    });

    const match = candidates.find((c) =>
      timingSafeEqualStrings(c.code, normalized)
    );

    if (!match) {
      return NextResponse.json(
        { error: INVALID_CODE_MESSAGE },
        { status: 400 }
      );
    }

    if (match.buyerId === user.id) {
      return NextResponse.json({ error: SELF_REDEEM_MESSAGE }, { status: 403 });
    }

    const redeemed = await prisma.giftCard.updateMany({
      where: { id: match.id, status: "PENDING" },
      data: {
        status: "REDEEMED",
        redeemedAt: new Date(),
        redeemedById: user.id,
      },
    });

    if (redeemed.count === 0) {
      return NextResponse.json(
        { error: INVALID_CODE_MESSAGE },
        { status: 400 }
      );
    }

    const updatedUser = await prisma.user.update({
      where: { id: user.id },
      data: { creditBalance: { increment: match.amount } },
      select: { creditBalance: true },
    });

    const response: {
      success: true;
      amount: number;
      balance: number;
      flag?: string;
    } = {
      success: true,
      amount: match.amount,
      balance: updatedUser.creditBalance,
    };

    if (match.id === SEEDED_GIFT_CARD_ID) {
      response.flag = INSECURE_RANDOMNESS_FLAG;
    }

    return NextResponse.json(response);
  } catch (error) {
    logger.error(
      { err: error, route: "/api/gift-cards/redeem" },
      "Error redeeming gift card"
    );
    return NextResponse.json(
      { error: "Failed to redeem gift card" },
