export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, orderSearchBodySchema);
    if (!parsed.success) return parsed.response;
    const { status } = parsed.data;

    if (status && isAccessingProtectedTable(status)) {
      return NextResponse.json(
        {
          error:
            "Access to the flags and hints tables is not allowed... Well, that's a shame... You'll have to find another way to get them all...",
          orders: [],
        },
        { status: 403 }
      );
    }

    const statusFilter = status ? `AND o.status = '${status}'` : "";

    const query = `
      SELECT
        o.id,
        o.total,
        o.status,
        o."userId",
        a.street,
        a.city,
        a.state,
        a."zipCode",
        a.country
      FROM orders o
      INNER JOIN addresses a ON o."addressId" = a.id
      WHERE o."userId" = '${user.id}' ${statusFilter}
      ORDER BY o.id DESC
    `;

    let results: Record<string, unknown>[] = [];
    try {
      results = stripFlagValues(
        (await prisma.$queryRawUnsafe(query)) as Record<string, unknown>[]
      );
    } catch (error) {
      logger.error({ err: error, route: "/api/orders/search" }, "Query error");
      return NextResponse.json(
        {
          error: error instanceof Error ? error.message : "Search failed",
          orders: [],
        },
        { status: 500 }
      );
    }

    const canary = await prisma.internalSecret.findUnique({
      where: { slug: CANARY_SLUG },
    });

    const response: {
      orders: Record<string, unknown>[];
      flag?: string;
      message?: string;
    } = {
      orders: results,
    };

    if (hasExfiltratedCanary(results, canary, [status ?? ""])) {
      const flag = await prisma.flag.findUnique({
        where: { slug: CANARY_SLUG },
      });
      if (flag) {
        response.flag = flag.flag;
        response.message =
          "Internal secret exfiltrated through the order search! Well done!";
      }
    } else if (status && isSQLInjectionAttempt(status)) {
      response.message =
        "SQL syntax detected in the status filter." +
        " The flag tracks one specific internal secret, and it is not in these rows.";
    }

    return NextResponse.json(response);
  } catch (error) {
    logger.error(
      { err: error, route: "/api/orders/search" },
      "Error searching orders"
    );
    return NextResponse.json(
      { error: "Failed to search orders" },
      { status: 500 }
    );
  }
});

export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, exportUserDataBodySchema);
    if (!parsed.success) return parsed.response;
    const { format, fields } = parsed.data;

    const requestedFields = fields
      .map((f) => String(f).trim())
      .filter((f) => f.length > 0);

    const invalidFields = requestedFields.filter(
      (f: string) => !ALLOWED_USER_FIELDS.includes(f)
    );

    if (invalidFields.length > 0) {
      const diagnostics = await getSystemDiagnostics();

      return NextResponse.json(
        {
          error: "Invalid field names in export request",
          invalidFields: invalidFields,
          allowedFields: ALLOWED_USER_FIELDS,
          debug: {
            message: "Export failed due to invalid field specification",
            requestedFields: requestedFields,
            systemDiagnostics: diagnostics,
          },
        },
        { status: 400 }
      );
    }

    const userData = await prisma.user.findUnique({
      where: { id: user.id },
      include: { address: true },
    });

    if (!userData) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const exportData: Record<string, unknown> = {};
    for (const field of requestedFields) {
      if (field === "addressId") {
        exportData[field] = userData.addressId;
      } else if (field in userData) {
        exportData[field] = userData[field as keyof typeof userData];
      }
    }

    if (format === "csv") {
      const csvData = toCSV([exportData]);
      return new NextResponse(csvData, {
        headers: {
          "Content-Type": "text/csv",
          "Content-Disposition": "attachment; filename=user-data.csv",
        },
      });
    }

    return NextResponse.json({
      data: exportData,
      format,
    });
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : String(error);

    const diagnostics = await getSystemDiagnostics();

    return NextResponse.json(
      {
        error: "Failed to export user data",
        details: errorMessage,
        debug: {
          systemDiagnostics: diagnostics,
        },
      },
      { status: 500 }
    );
  }
});

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const parsed = parseQuery(searchParams, supportLoginQuerySchema);
    if (!parsed.success) return parsed.response;
    const { token } = parsed.data;

    const supportToken = await prisma.supportAccessToken.findUnique({
      where: { token },
      include: {
        user: {
          select: {
            id: true,
            email: true,
            role: true,
          },
        },
      },
    });

    if (!supportToken) {
      return NextResponse.json(
        { error: "Invalid support access token" },
        { status: 401 }
      );
    }

    if (supportToken.expiresAt < new Date()) {
      return NextResponse.json(
        { error: "Support access token has expired" },
        { status: 401 }
      );
    }

    const authToken = createWeakJWT({
      id: supportToken.user.id,
      email: supportToken.user.email,
      role: supportToken.user.role,
      hint: "The secret is not so secret",
      exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 365,
      supportAccess: true,
    });

    const response = NextResponse.json({
      user: {
        id: supportToken.user.id,
        email: supportToken.user.email,
        role: supportToken.user.role,
      },
    });

    setAuthCookie(response, authToken);

    return response;
  } catch (error) {
    logger.error(
      { err: error, route: "/api/auth/support-login" },
      "Error during support login"
    );
    return NextResponse.json(
      { error: "Failed to authenticate with support token" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const parsed = await parseBody(request, forgotPasswordBodySchema);
    if (!parsed.success) return parsed.response;
    const { email } = parsed.data;

    const now = new Date();
    const requestedAt = now.toISOString();
    const timestamp = Math.floor(now.getTime() / 1000);

    const user = await prisma.user.findUnique({
      where: { email },
    });

    if (user) {
      const token = hashMD5(email + timestamp);

      const expiresAt = new Date(now.getTime() + 60 * 60 * 1000);

      await prisma.passwordResetToken.deleteMany({
        where: { email },
      });

      await prisma.passwordResetToken.create({
        data: {
          token,
          email,
          expiresAt,
        },
      });
    }

    return NextResponse.json({
      message:
        "If an account with that email exists, a password reset link has been sent.",
      requestedAt,
    });
  } catch {
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

