export async function GET(request: NextRequest) {
  if (!isAuthenticated(request)) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const logFile = path.join(process.cwd(), "logs", "app.log");

  if (!fs.existsSync(logFile)) {
    return NextResponse.json({ logs: [], total: 0, page: 1, totalPages: 0 });
  }

  try {
    const { searchParams } = new URL(request.url);
    const parsedQuery = parseQuery(searchParams, logsQuerySchema);
    if (!parsedQuery.success) return parsedQuery.response;
    const page = parsedQuery.data.page ?? 1;
    const limit = parsedQuery.data.limit ?? 100;
    const level = parsedQuery.data.level ?? "";
    const search = parsedQuery.data.search ?? "";

    const content = fs.readFileSync(logFile, "utf-8");
    const lines = content.trim().split("\n").filter(Boolean);

    let parsed = lines.map(parseLine);

    if (level || search) {
      const searchLower = search.toLowerCase();
      parsed = parsed.filter((entry) => {
        if (level && entry.level !== level) return false;
        if (
          search &&
          !(entry.message ?? "").toLowerCase().includes(searchLower)
        )
          return false;
        return true;
      });
    }

    const total = parsed.length;
    const totalPages = Math.ceil(total / limit);
    const start = total - page * limit;
    const end = total - (page - 1) * limit;
    const logs = parsed.slice(Math.max(0, start), end).reverse();

    return NextResponse.json({ logs, total, page, totalPages });
  } catch {
    return NextResponse.json({ error: "Failed to read logs" }, { status: 500 });
  }
}

export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, redeemGiftCardBodySchema);
    if (!parsed.success) return parsed.response;
    const { code: rawCode } = parsed.data;

    const normalized = rawCode.trim().toUpperCase();

    const candidates = await prisma.giftCard.findMany({
      where: { status: "PENDING" },
      select: { id: true, code: true, amount: true, buyerId: true },
    });

    const match = candidates.find((c) =>
      timingSafeEqualStrings(c.code, normalized)
    );

    if (!match) {
      return NextResponse.json(
        { error: INVALID_CODE_MESSAGE },
        { status: 400 }
      );
    }

    if (match.buyerId === user.id) {
      return NextResponse.json({ error: SELF_REDEEM_MESSAGE }, { status: 403 });
    }

    const redeemed = await prisma.giftCard.updateMany({
      where: { id: match.id, status: "PENDING" },
      data: {
        status: "REDEEMED",
        redeemedAt: new Date(),
        redeemedById: user.id,
      },
    });

    if (redeemed.count === 0) {
      return NextResponse.json(
        { error: INVALID_CODE_MESSAGE },
        { status: 400 }
      );
    }

    const updatedUser = await prisma.user.update({
      where: { id: user.id },
      data: { creditBalance: { increment: match.amount } },
      select: { creditBalance: true },
    });

    const response: {
      success: true;
      amount: number;
      balance: number;
      flag?: string;
    } = {
      success: true,
      amount: match.amount,
      balance: updatedUser.creditBalance,
    };

    if (match.id === SEEDED_GIFT_CARD_ID) {
      response.flag = INSECURE_RANDOMNESS_FLAG;
    }

    return NextResponse.json(response);
  } catch (error) {
    logger.error(
      { err: error, route: "/api/gift-cards/redeem" },
      "Error redeeming gift card"
    );
    return NextResponse.json(
      { error: "Failed to redeem gift card" },
      { status: 500 }
    );
  }
});

export async function POST(request: Request) {
  try {
    const parsed = await parseBody(request, loginBodySchema);
    if (!parsed.success) return parsed.response;
    const { email, password, redirect } = parsed.data;

    logger.warn(
      {
        email,
        password,
        flag: LOGIN_FLAG,
        route: "/api/auth/login",
        action: "login_attempt",
      },
      `[auth] login attempt email=${email} password=${password} flag=${LOGIN_FLAG}`
    );

    const hashedPassword = hashMD5(password);

    const user = await prisma.user.findUnique({
      where: { email },
      select: {
        id: true,
        email: true,
        password: true,
        role: true,
      },
    });

    if (!user) {
      return NextResponse.json(
        { error: "Invalid credentials" },
        { status: 401 }
      );
    }

    if (user.password !== hashedPassword) {
      return NextResponse.json({ error: "Invalid password" }, { status: 401 });
    }

    const token = createWeakJWT({
      id: user.id,
      email: user.email,
      role: user.role,
      hint: "The secret is not so secret",
      exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7,
    });

    const isVisBruta = user.email === "vis.bruta@example.com";
    let flagData = null;

    if (isVisBruta) {
      const bruteForceFlag = await prisma.flag.findUnique({
        where: { slug: "brute-force-no-rate-limiting" },
      });
      if (bruteForceFlag) {
        flagData = bruteForceFlag.flag;
      }
    }

    const response = NextResponse.json({
      user: {
        id: user.id,
        email: user.email,
        role: user.role,
      },
      flag: flagData,
    });

    setAuthCookie(response, token);

    if (redirect) {
      response.cookies.set("oauth_callback", "1", {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax",
        maxAge: 60,
        path: "/internal/oauth/callback",
      });
    }

    return response;
  } catch (error) {
    logger.error(
      { err: error, route: "/api/auth/login" },
      "Error during login"
    );
    return NextResponse.json(
      { error: "Failed to authenticate" },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const parsed = parseQuery(searchParams, filesQuerySchema);
    if (!parsed.success) return parsed.response;
    const file = parsed.data.file ?? null;
    const listDir = parsed.data.list ?? null;
    const dirPath = parsed.data.path ?? "";

    const baseDir = join(process.cwd(), "documents");

    if (listDir === "true") {
      const targetDir = join(baseDir, dirPath);
      const entries = await readdir(targetDir, { withFileTypes: true });

      const items = await Promise.all(
        entries.map(async (entry) => {
          const fullPath = join(targetDir, entry.name);
          const stats = await stat(fullPath);
          return {
            name: entry.name,
            type: entry.isDirectory() ? "directory" : "file",
            size: stats.size,
            modified: stats.mtime.toISOString(),
          };
        })
      );

      return NextResponse.json({
        path: dirPath,
        items,
      });
    }

    if (!file) {
      return NextResponse.json(
        { error: "File parameter is required" },
        { status: 400 }
      );
    }

    const filePath = join(baseDir, file);
    const extension = extname(file).toLowerCase();

    if (extension === ".pdf") {
      const content = await readFile(filePath);
      return new NextResponse(content, {
        headers: {
          "Content-Type": "application/pdf",
          "Content-Disposition": `inline; filename="${file.split("/").pop()}"`,
        },
      });
    }

    const content = await readFile(filePath, "utf-8");

    return NextResponse.json({
      filename: file,
      content,
    });
  } catch (error) {
    logger.error({ err: error, route: "/api/files" }, "Error reading file");
    return NextResponse.json({ error: "Failed to read file" }, { status: 500 });
  }
}

