export async function POST(request: Request) {
  try {
    const parsed = await parseBody(request, signupBodySchema);
    if (!parsed.success) return parsed.response;
    const body = parsed.data;
    const { email, password } = body;

    const existingUser = await prisma.user.findUnique({
      where: { email },
    });

    if (existingUser) {
      return NextResponse.json(
        { error: "Email already registered" },
        { status: 409 }
      );
    }

    let defaultAddress = await prisma.address.findUnique({
      where: { id: DEFAULT_ADDRESS_ID },
    });

    if (!defaultAddress) {
      defaultAddress = await prisma.address.create({
        data: {
          id: DEFAULT_ADDRESS_ID,
          street: "123 Main Street",
          city: "New York",
          state: "NY",
          zipCode: "10001",
          country: "USA",
        },
      });
    }

    const hashedPassword = hashMD5(password);

    const userData: {
      email: string;
      password: string;
      addressId: string;
      role?: UserRole;
    } = {
      email,
      password: hashedPassword,
      addressId: defaultAddress.id,
    };

    if (body.role) {
      userData.role = body.role as UserRole;
    }

    const user = await prisma.user.create({
      data: userData,
      select: {
        id: true,
        email: true,
        role: true,
      },
    });

    const token = createWeakJWT({
      id: user.id,
      email: user.email,
      role: user.role,
      hint: "The secret is not so secret",
      exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7,
    });

    const response = NextResponse.json({
      user: {
        id: user.id,
        email: user.email,
        role: user.role,
      },
    });

    setAuthCookie(response, token);

    return response;
  } catch (error) {
    logger.error(
      { err: error, route: "/api/auth/signup" },
      "Error during signup"
    );
    return NextResponse.json(
      { error: "Failed to create account" },
      { status: 500 }
    );
  }
}

export const POST = withAdminAuth(
  async (request: NextRequest, _context, _user) => {
    try {
      const rawXml = await request.text();

      if (!rawXml.trim()) {
        return NextResponse.json(
          { error: "Empty request body. Please provide XML data." },
          { status: 400 }
        );
      }

      const doc = libxmljs.parseXmlString(rawXml, {
        noent: true,
        dtdload: true,
      });

      const root = doc.root();
      if (!root || root.name() !== "order") {
        return NextResponse.json(
          {
            error: "Invalid XML structure. Expected root element <order>.",
            debug: {
              config: SUPPLIER_REGISTRY_PATH,
              message: "The XML must match the supplier order schema.",
              expected: ["supplierId", "orderId", "total", "notes (optional)"],
            },
          },
          { status: 400 }
        );
      }

      const getText = (name: string) =>
        (root.get(name) as libxmljs.Element | null)?.text()?.trim() || "";

      const supplierId = getText("supplierId");
      const orderId = getText("orderId");
      const total = parseFloat(getText("total")) || 0;
      const notes = getText("notes");

      if (!supplierId || !orderId) {
        return NextResponse.json(
          {
            error: "Missing required fields: supplierId and orderId.",
            debug: {
              config: SUPPLIER_REGISTRY_PATH,
              received: {
                supplierId: supplierId || null,
                orderId: orderId || null,
              },
            },
          },
          { status: 400 }
        );
      }

      const supplierOrder = await prisma.supplierOrder.create({
        data: {
          supplierId,
          orderId,
          total,
          notes: notes || null,
        },
      });

      return NextResponse.json({
        message: "Supplier order imported successfully.",
        order: {
          id: supplierOrder.id,
          supplierId: supplierOrder.supplierId,
          orderId: supplierOrder.orderId,
          total: supplierOrder.total,
          notes: supplierOrder.notes,
          createdAt: supplierOrder.createdAt,
        },
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Unknown error";
      return NextResponse.json(
        {
          error: `Failed to parse XML: ${message}`,
        },
        { status: 400 }
      );
    }
  }
);

export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, addCartItemBodySchema);
    if (!parsed.success) return parsed.response;
    const { productId, quantity } = parsed.data;

    const product = await prisma.product.findUnique({
      where: { id: productId },
    });

    if (!product) {
      return NextResponse.json({ error: "Product not found" }, { status: 404 });
    }

    let cart = await prisma.cart.findFirst({
      where: { userId: user.id },
      include: { cartItems: true },
    });

    if (!cart) {
      cart = await prisma.cart.create({
        data: {
          userId: user.id,
        },
        include: { cartItems: true },
      });
    }

    const existingCartItem = cart.cartItems.find(
      (item) => item.productId === productId
    );

    if (existingCartItem) {
      await prisma.cartItem.update({
        where: { id: existingCartItem.id },
        data: {
          quantity: existingCartItem.quantity + quantity,
        },
      });
    } else {
      await prisma.cartItem.create({
        data: {
          cartId: cart.id,
          productId: productId,
          quantity: quantity,
        },
      });
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    logger.error(
      { err: error, route: "/api/cart/add" },
      "Error adding to cart"
    );
    return NextResponse.json(
      { error: "Failed to add item to cart" },
      { status: 500 }
    );
  }
});

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> }
) {
  const { path } = await params;
  const filename = path.join("/");

  if (filename.includes("..") || filename.includes("\0")) {
    return NextResponse.json({ error: "Invalid path" }, { status: 400 });
  }

  const filepath = join(process.cwd(), "uploads", filename);

  if (!existsSync(filepath)) {
    return NextResponse.json({ error: "File not found" }, { status: 404 });
  }

  const ext = filename.substring(filename.lastIndexOf(".")).toLowerCase();
  const contentType = MIME_TYPES[ext];

  if (!contentType) {
    return NextResponse.json(
      { error: "Unsupported file type" },
      { status: 400 }
    );
  }

  const fileBuffer = await readFile(filepath);

  return new NextResponse(fileBuffer, {
    headers: {
      "Content-Type": contentType,
      "Cache-Control": "public, max-age=31536000, immutable",
    },
  });
}

export async function POST(request: NextRequest) {
  try {
    const parsed = await parseBody(request, resetPasswordBodySchema);
    if (!parsed.success) return parsed.response;
    const { token, password } = parsed.data;

    const resetToken = await prisma.passwordResetToken.findUnique({
      where: { token },
    });

    if (!resetToken) {
      return NextResponse.json(
        { error: "Invalid or expired reset token" },
        { status: 400 }
      );
    }

    if (resetToken.used) {
      return NextResponse.json(
        { error: "This reset token has already been used" },
        { status: 400 }
      );
    }

    if (resetToken.expiresAt < new Date()) {
      return NextResponse.json(
        { error: "This reset token has expired" },
        { status: 400 }
      );
    }

    const user = await prisma.user.findUnique({
      where: { email: resetToken.email },
    });

    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 400 });
    }

    const hashedPassword = hashMD5(password);

    await prisma.user.update({
      where: { id: user.id },
      data: { password: hashedPassword },
    });

    await prisma.passwordResetToken.update({
      where: { id: resetToken.id },
      data: { used: true },
    });

    const response: { message: string; flag?: string } = {
      message: "Your password has been reset successfully.",
    };

    const flag = await prisma.flag.findUnique({
      where: { slug: "insecure-password-reset" },
    });

    if (flag) {
      response.flag = flag.flag;
    }

    return NextResponse.json(response);
  } catch {
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

