async function mcpRequest(
  serverUrl: string,
  method: string,
  params?: Record<string, unknown>,
  headers?: Record<string, string>
) {
  const response = await fetch(serverUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...headers,
    },
    body: JSON.stringify({
      jsonrpc: "2.0",
      id: crypto.randomUUID(),
      method,
      params,
    }),
  });
  return response.json();
}

