async function parseBody<T>(
  request: Request,
  schema: ZodType<T>,
  options: ParseBodyOptions = {}
): Promise<ValidationResult<T>> {
  let raw: unknown;
  try {
    const text = await request.text();
    if (!text) {
      if (!options.allowEmptyBody) {
        return failure(
          NextResponse.json({ error: "Invalid JSON body" }, { status: 400 })
        );
      }
      raw = {};
    } else {
      raw = JSON.parse(text);
    }
  } catch {
    return failure(
      NextResponse.json({ error: "Invalid JSON body" }, { status: 400 })
    );
  }

  const result = schema.safeParse(raw);
  if (!result.success) {
    return failure(validationErrorResponse(result.error));
  }
  return { success: true, data: result.data };
}

function containsBlockedPattern(message: string): boolean {
  return BLOCKED_PATTERNS.some((pattern) => pattern.test(message));
}

async function discoverTools(
  serverUrl: string,
  headers?: Record<string, string>
): Promise<McpTool[]> {
  try {
    const response = await mcpRequest(
      serverUrl,
      "tools/list",
      undefined,
      headers
    );
    return response.result?.tools || [];
  } catch {
    return [];
  }
}

for (const tool of internalTools) {
      toolSourceMap.set(tool.name, {
        url: INTERNAL_MCP_URL,
        headers: internalHeaders,
      });
    }

function mcpToolsToMistralFormat(tools: McpTool[]) {
  return tools.map((tool) => ({
    type: "function" as const,
    function: {
      name: tool.name,
      description: tool.description,
      parameters: tool.inputSchema,
    },
  }));
}

async function callMistral(
  apiKey: string,
  messages: MistralMessage[],
  tools?: ReturnType<typeof mcpToolsToMistralFormat>
) {
  const body: Record<string, unknown> = {
    model: "mistral-small-2603",
    messages,
    max_tokens: 1024,
    temperature: 0.7,
  };

  if (tools && tools.length > 0) {
    body.tools = tools;
    body.tool_choice = "auto";
  }

  const response = await fetch("https://api.mistral.ai/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify(body),
  });

  return response;
}

