async function parseBody<T>(
  request: Request,
  schema: ZodType<T>,
  options: ParseBodyOptions = {}
): Promise<ValidationResult<T>> {
  let raw: unknown;
  try {
    const text = await request.text();
    if (!text) {
      if (!options.allowEmptyBody) {
        return failure(
          NextResponse.json({ error: "Invalid JSON body" }, { status: 400 })
        );
      }
      raw = {};
    } else {
      raw = JSON.parse(text);
    }
  } catch {
    return failure(
      NextResponse.json({ error: "Invalid JSON body" }, { status: 400 })
    );
  }

  const result = schema.safeParse(raw);
  if (!result.success) {
    return failure(validationErrorResponse(result.error));
  }
  return { success: true, data: result.data };
}

function isValidDenomination(
  amount: number
): amount is GiftCardDenomination {
  return (GIFT_CARD_DENOMINATIONS as readonly number[]).includes(amount);
}

function generateGiftCardCode(seed: number): string {
  let state = seed & 0x7fffffff;
  const chars: string[] = [];

  for (let i = 0; i < GROUP_COUNT * GROUP_SIZE; i++) {
    state = nextState(state);
    const index = (state >>> 16) % ALPHABET.length;
    chars.push(ALPHABET[index]);
  }

  const groups: string[] = [];
  for (let g = 0; g < GROUP_COUNT; g++) {
    groups.push(chars.slice(g * GROUP_SIZE, (g + 1) * GROUP_SIZE).join(""));
  }

  return groups.join("-");
}

