async (
  request: NextRequest,
  orderId: string,
  user: JWTPayload
): Promise<NextResponse> => {
  try {
    if (user.role !== "ADMIN") {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const contentType = request.headers.get("content-type");
    const parsed = contentType?.includes("application/x-www-form-urlencoded")
      ? await parseFormData(request, updateOrderStatusBodySchema)
      : await parseBody(request, updateOrderStatusBodySchema);
    if (!parsed.success) return parsed.response;
    const status = parsed.data.status;

    const validStatuses: Array<
      "PENDING" | "PROCESSING" | "SHIPPED" | "DELIVERED" | "CANCELLED"
    > = ["PENDING", "PROCESSING", "SHIPPED", "DELIVERED", "CANCELLED"];
    if (
      !status ||
      !validStatuses.includes(
        status as
          | "PENDING"
          | "PROCESSING"
          | "SHIPPED"
          | "DELIVERED"
          | "CANCELLED"
      )
    ) {
      return NextResponse.json(
        {
          error: "Invalid status. Must be one of: " + validStatuses.join(", "),
        },
        { status: 400 }
      );
    }

    const order = await prisma.order.findUnique({
      where: { id: orderId },
    });

    if (!order) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    const updatedOrder = await prisma.order.update({
      where: { id: orderId },
      data: {
        status: status as
          | "PENDING"
          | "PROCESSING"
          | "SHIPPED"
          | "DELIVERED"
          | "CANCELLED",
      },
    });





    const referer = request.headers.get("referer");
    const hasBrowserMetadata =
      referer !== null && request.headers.get("sec-fetch-site") !== null;
    const firedByAdminUi = referer?.includes("/admin") ?? false;

    const response: {
      success: boolean;
      order: {
        id: string;
        status: string;
      };
      flag?: string;
      message?: string;
    } = {
      success: true,
      order: {
        id: updatedOrder.id,
        status: updatedOrder.status,
      },
    };

    if (hasBrowserMetadata && !firedByAdminUi) {
      const csrfFlag = await prisma.flag.findUnique({
        where: { slug: "cross-site-request-forgery" },
      });
      if (csrfFlag) {
        response.flag = csrfFlag.flag;
        response.message =
          "An authenticated admin action, triggered by a page the admin never meant to trust. Well done!";
