function readBearerToken(request: NextRequest): string | null {
  const header = request.headers.get("authorization");
  if (!header) {
    return null;
  }

  const [scheme, value] = header.split(" ");
  if (scheme?.toLowerCase() !== "bearer" || !value?.trim()) {
    return null;
  }

  return value.trim();
}

function verifyPartnerToken(token: string): PartnerTokenClaims | null {
  const parts = token.split(".");
  if (parts.length !== 3) {
    return null;
  }

  const [header, payload, signature] = parts;
  const signingInput = `${header}.${payload}`;

  const algorithm = decodeSegment<{ alg?: string }>(header)?.alg;
  const key = getPartnerTokenKey();

  let signatureIsValid: boolean;
  try {
    if (algorithm === "RS256") {
      signatureIsValid = crypto.verify(
        "RSA-SHA256",
        Buffer.from(signingInput),
        { key },
        Buffer.from(signature, "base64url")
      );
    } else if (algorithm === "HS256") {
      signatureIsValid =
        crypto
          .createHmac("sha256", key)
          .update(signingInput)
          .digest("base64url") === signature;
    } else {
      return null;
    }
  } catch {
    return null;
  }

  if (!signatureIsValid) {
    return null;
  }

  const claims = decodeSegment<PartnerTokenClaims>(payload);
  if (!claims?.sub) {
    return null;
  }

  if (claims.exp && claims.exp < Math.floor(Date.now() / 1000)) {
    return null;
  }

  return claims;
}

