async function parseBody<T>(
  request: Request,
  schema: ZodType<T>,
  options: ParseBodyOptions = {}
): Promise<ValidationResult<T>> {
  let raw: unknown;
  try {
    const text = await request.text();
    if (!text) {
      if (!options.allowEmptyBody) {
        return failure(
          NextResponse.json({ error: "Invalid JSON body" }, { status: 400 })
        );
      }
      raw = {};
    } else {
      raw = JSON.parse(text);
    }
  } catch {
    return failure(
      NextResponse.json({ error: "Invalid JSON body" }, { status: 400 })
    );
  }

  const result = schema.safeParse(raw);
  if (!result.success) {
    return failure(validationErrorResponse(result.error));
  }
  return { success: true, data: result.data };
}

function isAccessingProtectedTable(input: string): boolean {
  return /\b(FLAGS|HINTS)\b/.test(input.toUpperCase());
}

(
  payload: unknown,
  canary: { token: string } | null,
  supplied: string[]
): boolean => {
  if (!canary) return false;
  if (supplied.some((value) => value.includes(canary.token))) return false;
  return JSON.stringify(payload).includes(canary.token);
}

function isSQLInjectionAttempt(input: string): boolean {
  const upperInput = input.toUpperCase();
  return SQL_KEYWORDS.some((keyword) => upperInput.includes(keyword));
}

