function buildExposedRepository(flag: string): Map<string, Buffer> {
  const store: ObjectStore = new Map();
  const commits = writeHistory(store);
  const head = commits.at(-1)!;
  const { message: subject, files } = HISTORY.at(-1)!;

  const stashedTree = writeTree(store, {
    ...files,
    ".env.production": envProduction(flag),
  });
  const reference = `${head.slice(0, 7)} ${subject}`;
  const indexCommit = writeCommit(store, {
    tree: stashedTree,
    parents: [head],
    timestamp: STASHED_AT,
    message: `index on main: ${reference}`,
  });
  writeCommit(store, {
    tree: stashedTree,
    parents: [head, indexCommit],
    timestamp: STASHED_AT,
    message: `WIP on main: ${reference}`,
  });

  const repository = new Map<string, Buffer>([
    ["HEAD", Buffer.from("ref: refs/heads/main\n")],
    ["config", Buffer.from(CONFIG)],
    ["description", Buffer.from(DESCRIPTION)],
    ["COMMIT_EDITMSG", Buffer.from(`${subject}\n`)],
    ["index", buildIndex(files)],
    ["refs/heads/main", Buffer.from(`${head}\n`)],
    ["logs/HEAD", Buffer.from(reflog(commits))],
    ["logs/refs/heads/main", Buffer.from(reflog(commits))],
  ]);
  for (const [sha, encoded] of store) {
    repository.set(
      `objects/${sha.slice(0, 2)}/${sha.slice(2)}`,
      deflateSync(encoded)
    );
  }
  return repository;
}

function listChildren(
  repository: Map<string, Buffer>,
  directory: string
): Map<string, number | null> {
  const children = new Map<string, number | null>();
  for (const [path, content] of repository) {
    if (!path.startsWith(directory)) continue;
    const rest = path.slice(directory.length);
    const slash = rest.indexOf("/");
    if (slash === -1) children.set(rest, content.length);
    else children.set(rest.slice(0, slash + 1), null);
  }
  return children;
}

function renderListing(
  directory: string,
  children: Map<string, number | null>
): string {
  const title = `Index of ${PUBLIC_ROOT}${directory}`;
  const rows = [...children]
    .sort(([a, aSize], [b, bSize]) => {
      if ((aSize === null) !== (bSize === null)) return aSize === null ? -1 : 1;
      return a < b ? -1 : 1;
    })
    .map(([name, size]) => {
      const padding = " ".repeat(Math.max(1, 51 - name.length));
      const column = String(size ?? "-").padStart(20);
      return `<a href="${name}">${name}</a>${padding}${LAST_MODIFIED}${column}\n`;
    });

  return `<html>
<head><title>${title}</title></head>
<body>
<h1>${title}</h1><hr><pre><a href="../">../</a>
${rows.join("")}</pre><hr></body>
</html>
`;
}

