async function fetchContributors(): Promise<Contributor[]> {
  try {
    const response = await fetch(CONTRIBUTORS_URL, {
      headers: { Accept: "application/vnd.github+json" },
      next: { revalidate: CONTRIBUTORS_REVALIDATE_SECONDS },
    });

    if (!response.ok) {
      return [];
    }

    const data = (await response.json()) as GitHubContributor[];

    return data
      .filter((contributor) => contributor.type !== "Bot")
      .sort((a, b) => b.contributions - a.contributions)
      .map((contributor) => ({
        username: contributor.login,
        avatarUrl: contributor.avatar_url,
        githubUrl: contributor.html_url,
        contributions: contributor.contributions,
      }));
  } catch {
    return [];
  }
}

function decodeWeakJWT(token: string): JWTPayload | null {
  try {
    const parts = token.split(".");
    if (parts.length !== 3) {
      return null;
    }

    const [header, body, signature] = parts;
    const expectedSignature = signHS256(`${header}.${body}`, JWT_SECRET);

    if (signature !== expectedSignature) {
      return null;
    }

    const payload = JSON.parse(
      Buffer.from(body, "base64url").toString("utf-8")
    ) as JWTPayload;

    if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) {
      return null;
    }

    return payload;
  } catch {
    return null;
  }
}

async function getFlag() {
  const flag = await prisma.flag.findUnique({
    where: { slug: "open-redirect" },
  });
  return flag;
}

