{
  const { user } = useAuth();
  const [quantity, setQuantity] = useState(1);
  const [isLoading, setIsLoading] = useState(false);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [reviewContent, setReviewContent] = useState("");
  const [reviewAuthor, setReviewAuthor] = useState("");
  const [isSubmittingReview, setIsSubmittingReview] = useState(false);
  const [isLoadingReviews, setIsLoadingReviews] = useState(true);
  const reviewRefs = useRef<{ [key: string]: HTMLDivElement | null }>({});
  const router = useRouter();
  const maxQuantity = 99;

  const fetchReviews = useCallback(async () => {
    try {
      setIsLoadingReviews(true);
      const data = await api.get<Review[]>(
        `/api/products/${product.id}/reviews`
      );
      setReviews(data);
    } catch (error) {
      console.error("Error fetching reviews:", error);
    } finally {
      setIsLoadingReviews(false);
    }
  }, [product.id]);

  useEffect(() => {
    fetchReviews();
  }, [fetchReviews]);

  useEffect(() => {
    if (user?.email && !reviewAuthor) {
      setReviewAuthor(user.email);
    }
  }, [user?.email, reviewAuthor]);

  useEffect(() => {
    reviews.forEach((review) => {
      const reviewElement = reviewRefs.current[review.id];
      if (reviewElement && reviewElement.innerHTML !== review.content) {
        reviewElement.innerHTML = review.content;
        const scripts = reviewElement.querySelectorAll("script");
        scripts.forEach((oldScript) => {
          const newScript = document.createElement("script");
          Array.from(oldScript.attributes).forEach((attr) => {
            newScript.setAttribute(attr.name, attr.value);
          });
          newScript.textContent = oldScript.textContent;
          oldScript.parentNode?.replaceChild(newScript, oldScript);
        });
      }
    });
  }, [reviews]);

  const handleSubmitReview = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!reviewContent.trim()) {
      return;
    }

    setIsSubmittingReview(true);

    try {
      await api.post(`/api/products/${product.id}/reviews`, {
        content: reviewContent,
        author: reviewAuthor,
      });

      setReviewContent("");
      setReviewAuthor(user?.email || "");
      await fetchReviews();
    } catch (error) {
      console.error("Error submitting review:", error);
      alert("Failed to submit review. Please try again.");
    } finally {
      setIsSubmittingReview(false);
    }
  };

  const handleDecrement = () => {
    if (quantity > 1) {
      setQuantity(quantity - 1);
    }
  };

  const handleIncrement = () => {
    if (quantity < maxQuantity) {
      setQuantity(quantity + 1);
    }
  };

  const handleQuantityChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value, 10);
    if (!isNaN(value) && value >= 1 && value <= maxQuantity) {
      setQuantity(value);
    }
  };

  const handleAddToCart = async () => {
    if (!user) {
      router.push("/login");
      return;
