    if (quantity > maxQuantity) {
      alert(`Maximum order limit is ${maxQuantity} per customer`);
      return;
    }

    setIsLoading(true);

    try {
      await api.post("/api/cart/add", {
        productId: product.id,
        quantity: quantity,
      });

      router.push("/cart");
