                  (() => {
                    const owaspUrl = getOwaspUrl(flag.owasp);
                    const className =
                      "rounded-full bg-indigo-100 px-3 py-1 text-xs font-semibold text-indigo-800 dark:bg-indigo-900/30 dark:text-indigo-300";
