prisma.flag.upsert({
      where: { slug: flag.slug },
      update: {
        ...flag,
        // Prisma leaves `undefined` alone, so a badge dropped upstream would
        // outlive it here while a fresh install comes up without it.
        cve: flag.cve ?? null,
        cwe: flag.cwe ?? null,
        owasp: flag.owasp ?? null,
      },
      create: flag,
    })

