helper_definition.text:
async function getFlagBySlug(slug: string): Promise<Flag | null> {
  try {
    const baseUrl = getBaseUrl();
    const response = await fetch(`${baseUrl}/api/flags/${slug}`, {
      cache: "no-store",
    });

    if (!response.ok) {
      return null;
    }

    return await response.json();
  } catch (error) {
    console.error("Error fetching flag:", error);
    return null;
  }
}

async function getFlagBySlug(slug: string): Promise<Flag | null> {
  try {
    const baseUrl = getBaseUrl();
    const response = await fetch(`${baseUrl}/api/flags/${slug}`, {
      cache: "no-store",
    });

    if (!response.ok) {
      return null;
    }

    return await response.json();
  } catch (error) {
    console.error("Error fetching flag:", error);
    return null;
  }
}

async function getMarkdownContent(filename: string): Promise<string> {
  try {
    const filePath = join(
      process.cwd(),
      "content",
      "vulnerabilities",
      filename
    );
    const content = await readFile(filePath, "utf-8");
    return content;
  } catch {
    throw new Error(`Failed to read markdown file: ${filename}`);
  }
}

