                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M14 5l7 7m0 0l-7 7m7-7H3"
                  />
                </svg>
              </a>
            )}
            <article className="p-8">
              <div className="markdown-content">
                <ReactMarkdown
                  remarkPlugins={[remarkGfm]}
                  components={{
                    h1: ({ children }) => (
                      <h1 className="mb-6 text-3xl font-bold text-slate-900 dark:text-slate-100">
                        {children}
                      </h1>
                    ),
                    h2: ({ children }) => (
                      <h2 className="mb-4 mt-8 text-2xl font-bold text-slate-900 dark:text-slate-100">
                        {children}
                      </h2>
                    ),
                    h3: ({ children }) => (
                      <h3 className="mb-3 mt-6 text-xl font-semibold text-slate-900 dark:text-slate-100">
                        {children}
                      </h3>
                    ),
                    p: ({ children }) => (
                      <p className="mb-4 leading-relaxed text-slate-700 dark:text-slate-300">
                        {children}
                      </p>
                    ),
                    ul: ({ children }) => (
                      <ul className="mb-4 ml-6 list-disc space-y-2 text-slate-700 dark:text-slate-300">
                        {children}
                      </ul>
                    ),
                    ol: ({ children }) => (
                      <ol className="mb-4 ml-6 list-decimal space-y-2 text-slate-700 dark:text-slate-300">
                        {children}
                      </ol>
                    ),
                    li: ({ children }) => (
                      <li className="leading-relaxed">{children}</li>
                    ),
                    code: ({ children, className }) => {
                      const isInline = !className;
                      return isInline ? (
                        <code className="rounded bg-slate-100 px-1.5 py-0.5 text-sm font-mono text-primary-600 dark:bg-slate-700 dark:text-primary-400">
                          {children}
                        </code>
                      ) : (
                        <code className={className}>{children}</code>
                      );
                    },
                    pre: ({ children }) => (
                      <pre className="mb-4 overflow-x-auto rounded-lg bg-slate-900 p-4 dark:bg-slate-950">
                        {children}
                      </pre>
                    ),
                    a: ({ href, children }) => (
                      <a
                        href={href}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="font-medium text-primary-600 underline transition-colors hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300"
                      >
                        {children}
                      </a>
                    ),
                    strong: ({ children }) => (
                      <strong className="font-semibold text-slate-900 dark:text-slate-100">
                        {children}
                      </strong>
                    ),
                    blockquote: ({ children }) => (
                      <blockquote className="my-4 border-l-4 border-primary-500 bg-slate-50 pl-4 italic text-slate-700 dark:border-primary-400 dark:bg-slate-800 dark:text-slate-300">
                        {children}
                      </blockquote>
                    ),
                  }}
                >
                  {markdownContent}
                </ReactMarkdown>
              </div>
            </article>
            {/* Deliberately placed after the writeup, not beside the link to
             * it: nobody asks a question when the full solution is one click
             * away. The moment someone needs the community is the one after
             * the walkthrough failed them. */}
            <p className="border-t border-slate-200 px-8 py-6 text-sm text-slate-600 dark:border-slate-800 dark:text-slate-400">
              Followed the walkthrough and it still will not fire?{" "}
              <a
                href={askAboutChallengeUrl(flag.slug)}
                target="_blank"
                rel="noopener noreferrer"
                className="font-medium text-primary-600 underline transition-colors hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300"
              >
                Ask about this challenge
                <span className="sr-only"> (opens in a new tab)</span>
              </a>{" "}
              — post your actual payloads and output.
            </p>
          </div>
        </section>
      </main>
      <Footer />
    </div>
  );
}

