async function getMarkdownContent(filename: string): Promise<string> {
  try {
    const filePath = join(
      process.cwd(),
      "content",
      "vulnerabilities",
      filename
    );
    const content = await readFile(filePath, "utf-8");
    return content;
  } catch {
    throw new Error(`Failed to read markdown file: ${filename}`);
  }
}

function formatSlug(slug: string): string {
  return slug
    .split("-")
    .map((word) => {
      const upper = word.toUpperCase();
      if (TITLE_OVERRIDES[upper]) return TITLE_OVERRIDES[upper];
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .join(" ");
}

function getCveUrl(cve: string): string {
  return `https://nvd.nist.gov/vuln/detail/${encodeURIComponent(cve)}`;
}

function askAboutChallengeUrl(slug: string): string {
  const params = new URLSearchParams({
    category: "stuck-on-a-challenge",
    title: `[Stuck] ${challengeTitle(slug)}`,
  });
  return `${GITHUB_DISCUSSIONS}/new?${params}`;
